#include <bits/stdc++.h>
using namespace std;

struct FastReader {
    std::istream& in;
    std::string token;

    FastReader() : in(std::cin) {}

    std::string next() {
        while (token.empty() || !(std::cin >> token)) {
            // read line if token is empty
            std::getline(in, token);
            if (token.empty()) continue;
            std::istringstream iss(token);
            iss >> token;
        }
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        std::string line;
        std::getline(in, line);
        return line;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    FastReader sc;

    int t = 1;
